    if (I.rep.down) { this.sel = (this.sel + 1) % this.choices.length; AE.Sfx && AE.Sfx.play('move'); }
    if (I.pressed.ok) { AE.Sfx && AE.Sfx.play('ok'); g.pop(this); this.done(this.sel); }
