    const a = new AE.Actor({ x: n.x, y: n.y, dir: n.dir === undefined ? 2 : n.dir, who: n.who, cast: !!(AE.MS && AE.MS[n.who] && AE.MS[n.who].idle), def: n, id: n.id || ('n' + i), home: [n.x, n.y], wait: AE.rand(120) });
