      if (D.type === 'echo') st.abil.echo.push({ pid: pid, id: P.id, lv: lvl, slot: slot, i: i });
      if (D.type === 'support') st.abil.support.push({ pid: pid, id: P.id, lv: lvl, slot: slot, i: i });
