AE.healAll = function () { AE.partyMembers().concat(AE.S_.reserve.map(function (id) { return AE.S_.m[id]; })).forEach(function (m) { if (!m) return; AE.calc(m.id); m.hp = m.maxhp; m.mp = m.maxmp; m.status = []; }); };
