  if (D.pipes) { ctx.fillStyle = 'rgba(80,100,110,.8)'; ctx.fillRect(0, 18, AE.W, 5); ctx.fillRect(0, 34, AE.W, 3); for (let x = 20; x < AE.W; x += 50) ctx.fillRect(x, 0, 4, hz); }
