    const col = f.hp <= 0 ? '#e05050' : f.hp < f.maxhp / 4 ? '#ffd040' : '#fff';
    AE.text(ctx, f.name, 100, y, active ? '#ffe080' : col);
    AE.text(ctx, f.hp + '/' + f.maxhp, 192, y, col, { align: 'right' });
