      if (I.rep.down) { this.hsel = (this.hsel + 1) % this.phand.length; AE.Sfx.play('move'); }
      if (I.pressed.ok) { this.stage = 'board'; AE.Sfx.play('ok'); while (this.board[this.cell]) this.cell = (this.cell + 1) % 9; }
