  EV.a1_exhibit = async function (e) { await AE.say(EXH[(e && e.n) || 0]); if ((e && e.n) === 2 && AE.S_.party.indexOf('lyra') >= 0) await cs.s('lyra', 'It\'s real. It\'s crying, very quietly.'); };
